   51	// NewDispatcher returns a dispatcher with the email and webhook channels.
   52	func NewDispatcher(s *store.Store, log *slog.Logger, now func() time.Time) *Dispatcher {
   53		d := &Dispatcher{
   54			store: s,
   55			senders: map[string]Sender{
   56				"email":   emailSender{log: log},
   57				"webhook": webhookSender{client: &webhook.Client{Log: log, Now: now}, now: now},
   58			},
   59			log:     log,
   60			now:     now,
   61			retries: make(map[string]int),
   62			stop:    make(chan struct{}),
   63		}
